namespace UniversalPOS.Domain.Entities;
public class AuditLog { public long Id {get; private set;} public int? UserId {get; private set;} public string Action {get; private set;}=string.Empty; public string EntityName {get; private set;}=string.Empty; public string? EntityId {get; private set;} public string? Details {get; private set;} public DateTime CreatedAtUtc {get; private set;}=DateTime.UtcNow; public string? TerminalCode {get; private set;} private AuditLog(){} public AuditLog(int? userId,string action,string entityName,string? entityId,string? details,string? terminalCode){if(string.IsNullOrWhiteSpace(action)||string.IsNullOrWhiteSpace(entityName))throw new ArgumentException("Action and entity name are required.");UserId=userId;Action=action.Trim();EntityName=entityName.Trim();EntityId=entityId;Details=details;TerminalCode=terminalCode;} }
